import React, { useState, useEffect } from 'react';
import axios from 'axios';

function App() {
  const [email, setEmail] = useState('');
  const [motDePasse, setMotDePasse] = useState('');
  const [connecte, setConnecte] = useState(false);
  const [user, setUser] = useState(null);
  const [token, setToken] = useState('');
  const [message, setMessage] = useState('');
  
  // États pour la gestion
  const [ongletActif, setOngletActif] = useState('dashboard');
  const [articles, setArticles] = useState([]);
  const [ventesJour, setVentesJour] = useState(null);
  const [panier, setPanier] = useState([]);
  const [articleSelectionne, setArticleSelectionne] = useState('');
  const [quantiteVente, setQuantiteVente] = useState(1);
  const [nouvelArticle, setNouvelArticle] = useState({
    reference: '',
    nom: '',
    description: '',
    prix_achat: '',
    prix_vente: '',
    quantite_stock: '',
    taille: '',
    couleur: ''
  });

  useEffect(() => {
    if (connecte) {
      chargerArticles();
      chargerVentesJour();
    }
  }, [connecte]);

  const chargerArticles = async () => {
    try {
      const response = await axios.get('http://127.0.0.1:5000/api/articles', {
        headers: { Authorization: `Bearer ${token}` }
      });
      setArticles(response.data);
    } catch (error) {
      console.error('Erreur chargement articles:', error);
    }
  };

  const chargerVentesJour = async () => {
    try {
      const response = await axios.get('http://127.0.0.1:5000/api/ventes/aujourdhui', {
        headers: { Authorization: `Bearer ${token}` }
      });
      setVentesJour(response.data);
    } catch (error) {
      console.error('Erreur chargement ventes:', error);
    }
  };

  const handleLogin = async () => {
    try {
      const response = await axios.post('http://127.0.0.1:5000/api/auth/login', {
        email: email,
        mot_de_passe: motDePasse
      });
      
      setUser(response.data.user);
      setToken(response.data.token);
      setConnecte(true);
      setMessage('');
      
      localStorage.setItem('token', response.data.token);
      localStorage.setItem('user', JSON.stringify(response.data.user));
      
    } catch (error) {
      setMessage('Email ou mot de passe incorrect');
    }
  };

  const handleLogout = () => {
    setConnecte(false);
    setUser(null);
    setToken('');
    setEmail('');
    setMotDePasse('');
    setOngletActif('dashboard');
    setArticles([]);
    setPanier([]);
    localStorage.removeItem('token');
    localStorage.removeItem('user');
  };

  const handleAjouterArticle = async () => {
    try {
      await axios.post('http://127.0.0.1:5000/api/articles', nouvelArticle, {
        headers: { Authorization: `Bearer ${token}` }
      });
      alert('✅ Article ajouté avec succès !');
      setNouvelArticle({
        reference: '',
        nom: '',
        description: '',
        prix_achat: '',
        prix_vente: '',
        quantite_stock: '',
        taille: '',
        couleur: ''
      });
      chargerArticles();
    } catch (error) {
      alert('❌ Erreur lors de l\'ajout de l\'article');
    }
  };

  const handleSupprimerArticle = async (id) => {
    if (window.confirm('Voulez-vous vraiment supprimer cet article ?')) {
      try {
        await axios.delete(`http://127.0.0.1:5000/api/articles/${id}`, {
          headers: { Authorization: `Bearer ${token}` }
        });
        chargerArticles();
      } catch (error) {
        alert('❌ Erreur lors de la suppression');
      }
    }
  };

  const handleAjouterAuPanier = () => {
    if (!articleSelectionne || quantiteVente < 1) {
      alert('Veuillez sélectionner un article et une quantité valide');
      return;
    }
    
    const article = articles.find(a => a.id === parseInt(articleSelectionne));
    
    if (!article) {
      alert('Article introuvable');
      return;
    }
    
    if (user.role === 'admin' && article.quantite_stock < quantiteVente) {
      alert(`Stock insuffisant ! Stock disponible: ${article.quantite_stock}`);
      return;
    }
    
    const articleDansPanier = panier.find(item => item.article_id === article.id);
    
    if (articleDansPanier) {
      setPanier(panier.map(item => 
        item.article_id === article.id 
          ? {...item, quantite: item.quantite + quantiteVente}
          : item
      ));
    } else {
      setPanier([...panier, {
        article_id: article.id,
        nom: article.nom,
        prix_vente: article.prix_vente,
        quantite: quantiteVente
      }]);
    }
    
    setArticleSelectionne('');
    setQuantiteVente(1);
  };

  const handleRetirerDuPanier = (articleId) => {
    setPanier(panier.filter(item => item.article_id !== articleId));
  };

  const handleValiderVente = async () => {
    if (panier.length === 0) {
      alert('Le panier est vide');
      return;
    }
    
    try {
      const response = await axios.post('http://127.0.0.1:5000/api/ventes', {
        articles: panier,
        mode_paiement: 'especes'
      }, {
        headers: { Authorization: `Bearer ${token}` }
      });
      
      alert(`✅ Vente enregistrée !\nFacture: ${response.data.vente.numero_facture}\nBénéfice: ${response.data.vente.benefice} FCFA`);
      
      setPanier([]);
      chargerArticles();
      chargerVentesJour();
    } catch (error) {
      alert('❌ ' + (error.response?.data?.message || 'Erreur lors de la vente'));
    }
  };

  const totalPanier = panier.reduce((total, item) => total + (item.prix_vente * item.quantite), 0);

  // Page de connexion
  if (!connecte) {
    return (
      <div style={styles.loginContainer}>
        <div style={styles.loginBox}>
          <h1>🏪 Gestion Boutique</h1>
          <h2>Connexion</h2>
          <input
            type="email"
            placeholder="Email"
            value={email}
            onChange={(e) => setEmail(e.target.value)}
            style={styles.input}
          />
          <input
            type="password"
            placeholder="Mot de passe"
            value={motDePasse}
            onChange={(e) => setMotDePasse(e.target.value)}
            style={styles.input}
          />
          <button onClick={handleLogin} style={styles.button}>
            Se connecter
          </button>
          {message && <p style={styles.error}>{message}</p>}
          <p style={styles.info}>Démo: admin@boutique.com / admin123</p>
        </div>
      </div>
    );
  }

  // Application principale
  return (
    <div style={styles.appContainer}>
      <nav style={styles.navbar}>
        <h2 style={styles.logo}>🏪 Boutique</h2>
        <div style={styles.navButtons}>
          <button 
            onClick={() => setOngletActif('dashboard')} 
            style={ongletActif === 'dashboard' ? styles.navButtonActive : styles.navButton}
          >
            📊 Tableau de bord
          </button>
          
          {user.role === 'admin' && (
            <button 
              onClick={() => setOngletActif('articles')} 
              style={ongletActif === 'articles' ? styles.navButtonActive : styles.navButton}
            >
              📦 Articles
            </button>
          )}
          
          <button 
            onClick={() => setOngletActif('vente')} 
            style={ongletActif === 'vente' ? styles.navButtonActive : styles.navButton}
          >
            💰 Vente
          </button>
        </div>
        <div style={styles.userInfo}>
          <span style={styles.userName}>{user.nom} ({user.role})</span>
          <button onClick={handleLogout} style={styles.logoutButton}>
            Déconnexion
          </button>
        </div>
      </nav>

      <main style={styles.mainContent}>
        {ongletActif === 'dashboard' && (
          <div>
            <h2>📊 Tableau de bord</h2>
            <div style={styles.statsGrid}>
              <div style={styles.statCard}>
                <h3>📦 Articles en stock</h3>
                <p style={styles.statNumber}>{articles.length}</p>
              </div>
              
              {user.role === 'admin' && (
                <>
                  <div style={styles.statCard}>
                    <h3>💰 Valeur du stock</h3>
                    <p style={styles.statNumber}>
                      {articles.reduce((total, art) => total + (art.prix_vente * (art.quantite_stock || 0)), 0).toFixed(0)} FCFA
                    </p>
                  </div>
                  <div style={styles.statCard}>
                    <h3>📈 Bénéfice potentiel</h3>
                    <p style={styles.statNumber}>
                      {articles.reduce((total, art) => total + ((art.prix_vente - art.prix_achat) * (art.quantite_stock || 0)), 0).toFixed(0)} FCFA
                    </p>
                  </div>
                </>
              )}
            </div>
            
            {ventesJour && (
              <div style={styles.welcomeCard}>
                <h3>📅 Ventes du jour</h3>
                <div style={{display: 'flex', gap: '30px', flexWrap: 'wrap', marginTop: '20px'}}>
                  <div>
                    <p><strong>Nombre de ventes:</strong> {ventesJour.stats.nombre_ventes || 0}</p>
                    <p><strong>Chiffre d'affaires:</strong> {ventesJour.stats.chiffre_affaires || 0} FCFA</p>
                    {user.role === 'admin' && (
                      <p style={{color: 'green'}}><strong>Bénéfice du jour:</strong> {ventesJour.stats.benefice || 0} FCFA</p>
                    )}
                  </div>
                </div>
              </div>
            )}
          </div>
        )}

        {ongletActif === 'articles' && user.role === 'admin' && (
          <div>
            <h2>📦 Gestion des articles</h2>
            
            <div style={styles.formCard}>
              <h3>➕ Ajouter un nouvel article</h3>
              <div style={styles.formGrid}>
                <input
                  placeholder="Référence *"
                  value={nouvelArticle.reference}
                  onChange={(e) => setNouvelArticle({...nouvelArticle, reference: e.target.value})}
                  style={styles.input}
                />
                <input
                  placeholder="Nom *"
                  value={nouvelArticle.nom}
                  onChange={(e) => setNouvelArticle({...nouvelArticle, nom: e.target.value})}
                  style={styles.input}
                />
                <input
                  placeholder="Prix d'achat (FCFA) *"
                  type="number"
                  value={nouvelArticle.prix_achat}
                  onChange={(e) => setNouvelArticle({...nouvelArticle, prix_achat: e.target.value})}
                  style={styles.input}
                />
                <input
                  placeholder="Prix de vente (FCFA) *"
                  type="number"
                  value={nouvelArticle.prix_vente}
                  onChange={(e) => setNouvelArticle({...nouvelArticle, prix_vente: e.target.value})}
                  style={styles.input}
                />
                <input
                  placeholder="Quantité en stock *"
                  type="number"
                  value={nouvelArticle.quantite_stock}
                  onChange={(e) => setNouvelArticle({...nouvelArticle, quantite_stock: e.target.value})}
                  style={styles.input}
                />
                <input
                  placeholder="Taille (ex: M, L, XL)"
                  value={nouvelArticle.taille}
                  onChange={(e) => setNouvelArticle({...nouvelArticle, taille: e.target.value})}
                  style={styles.input}
                />
                <input
                  placeholder="Couleur"
                  value={nouvelArticle.couleur}
                  onChange={(e) => setNouvelArticle({...nouvelArticle, couleur: e.target.value})}
                  style={styles.input}
                />
              </div>
              <button onClick={handleAjouterArticle} style={styles.button}>
                ✅ Ajouter l'article
              </button>
            </div>

            <div style={styles.tableCard}>
              <h3>📋 Articles en stock ({articles.length})</h3>
              {articles.length === 0 ? (
                <p style={{textAlign: 'center', color: '#999'}}>Aucun article pour le moment</p>
              ) : (
                <div style={{overflowX: 'auto'}}>
                  <table style={styles.table}>
                    <thead>
                      <tr>
                        <th>Référence</th>
                        <th>Nom</th>
                        <th>Prix d'achat</th>
                        <th>Prix de vente</th>
                        <th>Stock</th>
                        <th>Bénéfice/unité</th>
                        <th>Action</th>
                      </tr>
                    </thead>
                    <tbody>
                      {articles.map(article => (
                        <tr key={article.id}>
                          <td>{article.reference}</td>
                          <td>{article.nom}</td>
                          <td>{article.prix_achat} FCFA</td>
                          <td>{article.prix_vente} FCFA</td>
                          <td style={{
                            color: article.quantite_stock <= 5 ? 'red' : 'green',
                            fontWeight: 'bold'
                          }}>
                            {article.quantite_stock}
                          </td>
                          <td>{(article.prix_vente - article.prix_achat).toFixed(0)} FCFA</td>
                          <td>
                            <button 
                              onClick={() => handleSupprimerArticle(article.id)}
                              style={styles.deleteButton}
                            >
                              🗑️
                            </button>
                          </td>
                        </tr>
                      ))}
                    </tbody>
                  </table>
                </div>
              )}
            </div>
          </div>
        )}

        {ongletActif === 'vente' && (
          <div>
            <h2>💰 Nouvelle vente</h2>
            <div style={styles.venteContainer}>
              <div style={styles.venteLeft}>
                <h3>Sélectionner un article</h3>
                <select 
                  value={articleSelectionne}
                  onChange={(e) => setArticleSelectionne(e.target.value)}
                  style={styles.input}
                >
                  <option value="">-- Choisir un article --</option>
                  {articles.map(article => (
                    <option key={article.id} value={article.id}>
                      {article.nom} - {article.prix_vente} FCFA
                    </option>
                  ))}
                </select>
                
                <input
                  type="number"
                  placeholder="Quantité"
                  value={quantiteVente}
                  onChange={(e) => setQuantiteVente(parseInt(e.target.value))}
                  min="1"
                  style={styles.input}
                />
                
                <button onClick={handleAjouterAuPanier} style={styles.button}>
                  🛒 Ajouter au panier
                </button>
              </div>
              
              <div style={styles.venteRight}>
                <h3>Panier</h3>
                {panier.length === 0 ? (
                  <p style={{color: '#999'}}>Le panier est vide</p>
                ) : (
                  <>
                    <table style={styles.table}>
                      <thead>
                        <tr>
                          <th>Article</th>
                          <th>Qté</th>
                          <th>Prix</th>
                          <th>Total</th>
                          <th></th>
                        </tr>
                      </thead>
                      <tbody>
                        {panier.map(item => (
                          <tr key={item.article_id}>
                            <td>{item.nom}</td>
                            <td>{item.quantite}</td>
                            <td>{item.prix_vente} FCFA</td>
                            <td>{item.prix_vente * item.quantite} FCFA</td>
                            <td>
                              <button 
                                onClick={() => handleRetirerDuPanier(item.article_id)}
                                style={styles.deleteButton}
                              >
                                ✕
                              </button>
                            </td>
                          </tr>
                        ))}
                      </tbody>
                    </table>
                    
                    <div style={styles.totalSection}>
                      <h3>Total: {totalPanier} FCFA</h3>
                      <button onClick={handleValiderVente} style={styles.button}>
                        ✅ Valider la vente
                      </button>
                    </div>
                  </>
                )}
              </div>
            </div>
          </div>
        )}
      </main>
    </div>
  );
}

